// remoteWindow is set once a remote window connects (#240): it refuses the
// calls in READ_ONLY_BLOCKED (readonly.ts).
let remoteWindow = false;
let readOnlyMessage = 'Read-only remote (coming in a later version)';
export function setRemoteWindow(on: boolean, message: string) {
  remoteWindow = on;
  readOnlyMessage = message;
}

// These controls can replay their complete action, including refreshing the
// displayed setting when the new save succeeds.
const retryableSettings = new Set(['setCheckGlobalGitignore', 'setPRBadgesEnabled', 'setPRIncludeDrafts', 'setNestedScanDepth']);

export function settingsSaveFailed(e: unknown, retry: () => void) {
  if (e instanceof WindowError && e.code === 'config.changed') {
    pushNotice('error', e.message, [], retry);
    return;
  }
  pushNotice('error', e instanceof Error ? e.message : String(e));
}

// A remote window's calls fail with a WindowError in the user's language
// (readonly.ts); a local window's come back as they are.
export const bridge = guardCalls(calls, () => remoteWindow, () => readOnlyMessage, (e, name) => {
  const error = decodeWindowError(e, get(t));
  if (error instanceof WindowError && error.code === 'config.changed' && !retryableSettings.has(name)) {
    pushNotice('error', error.message);
  }
  return error;
});

// CallName is the name of a bridge call, as use:ro and blocked take it.
export type CallName = keyof typeof calls;

// ── Remote mode types (mirror cmd/gui/remote.go) ──
export type RemoteStateName = 'connecting' | 'installing' | 'connected' | 'failed' | 'disconnected';

export interface RemoteState {
  state: RemoteStateName;
  code?: string;
  hint?: string;
  detail?: string;
  alias: string;
  serverOS?: string;
  serverArch?: string;
  serverVersion?: string;
  truncated?: boolean;
  // While connecting, ssh has not logged in after a few seconds: an agent
  // may be waiting for approval, 1Password's in its menu bar or tray icon.
  waiting?: 'agent' | '1password';
  // The editor commands that open folders of the host (#243).
  remoteEditors?: string[] | null;
  // The editor chosen for this remote, absent for Auto (#287).
  editor?: string;
  // While connecting again after the link to the host's daemon dropped,
  // which attempt this is (#247).
  attempt?: number;
  attempts?: number;
  // Once connected: the connection resumed the host's daemon with every
  // event the window missed, so the window keeps what it shows (#247).
  resumed?: boolean;
}

export interface RemoteResult {
  error?: string;
  hint?: string;
}

export interface RemoteUninstallResult extends RemoteResult {
  needsConfirm: boolean;
  otherClients: number;
  done: boolean;
  rootKept: boolean;
}

export interface RemoteDoctorReport {
  version: string;
  commit: string;
  os: string;
  arch: string;
  home: string;
  configPath: string;
  configDirWritable: boolean;
  configDirExec: boolean;
  gitVersion: string;
  credentialFindings: CredentialFinding[] | null;
  roots?: RemoteDoctorRoot[];
}

/** Whether the server can read one clone root of the host (#245). */
export interface RemoteDoctorRoot {
  path: string;
  state: 'ok' | 'missing' | 'tcc' | 'denied' | 'unreadable';
}

export interface RemoteDoctorResult extends RemoteResult {
  report?: RemoteDoctorReport;
}

export interface RemotePathDTO {
  abs: string;
  exists: boolean;
  isDir: boolean;
  writable: boolean;
  error?: string;
}

// One Host line of this computer's ssh configuration (#330): the alias
// adding it uses, and every name on the line as written.
export interface SSHHost {
  alias: string;
  names: string[];
}

export interface RemotesList {
  enabled: boolean;
  // The alias this window shows, absent in the local window (#330).
  current?: string;
  remotes: {
    alias: string;
    serverDir?: string;
    editor?: string;
    // A window of this remote is running, with this connection state (#330).
    open?: boolean;
    state?: RemoteStateName;
    // What the host reported on its last connection (#330).
    serverOS?: string;
    serverArch?: string;
    serverVersion?: string;
    lastConnected?: string;
  }[];
  // The editor commands a remote can be set to (#287).
  remoteEditors?: string[] | null;
}

// ── Doctor types (mirror cmd/gui/app.go) ──
export interface DoctorToolDTO {
  name: string;
  displayName: string;
  purpose: string;
  found: boolean;
  path?: string;
  version?: string;
  required: boolean;
  requiredFor?: string;
  installHint?: string;
}

export interface DoctorReport {
  credentialFindings: CredentialFinding[];
  tools: DoctorToolDTO[];
  allOk: boolean;
  missingReq: number;
  missingOpt: number;
}

export interface DoctorPrecheckDTO {
  ok: boolean;
  summary?: string;
  hint?: string;
  missing?: DoctorToolDTO[];
}

export const events = createEventRouter(EventsOn);
